export const invalidateGetBudget = async (
 queryClient: QueryClient, budgetId: number, options?: InvalidateOptions
  ): Promise<QueryClient> => {

  await queryClient.invalidateQueries({ queryKey: withDefaultQueryOptions({ queryKey: getGetBudgetQueryKey(budgetId) }, { budgetId }).queryKey }, options);

  return queryClient;
}

